function rotate(grid,degrees=0){let out=grid.map(row=>row.map(c=>c?{...c}:null));for(let k=0;k<((degrees%360)+360)%360/90;k++){const R=out.length,C=out[0].length,next=Array.from({length:C},()=>Array(R));for(let r=0;r<R;r++)for(let c=0;c<C;c++)next[c][R-1-r]=out[r][c]?{type:out[r][c].type,rotation:(out[r][c].rotation+90)%360}:null;out=next}return out}
function validCombo(combo,allowed){return !!combo&&Object.keys(combo).every(k=>['id','name','grid'].includes(k))&&typeof combo.id==='string'&&/^custom_[a-z0-9_-]{1,80}$/.test(combo.id)&&typeof combo.name==='string'&&combo.name.trim().length>0&&combo.name.length<=50&&Array.isArray(combo.grid)&&combo.grid.length>=1&&combo.grid.length<=6&&Array.isArray(combo.grid[0])&&combo.grid[0].length>=1&&combo.grid[0].length<=6&&combo.grid.every(row=>Array.isArray(row)&&row.length===combo.grid[0].length&&row.every(c=>c===null||c&&allowed.includes(c.type)&&[0,90,180,270].includes(c.rotation)))}
function stamp(cells,grid,row,column,repeat=false){const R=cells.length,C=cells[0].length,H=grid.length,W=grid[0].length;if(!Number.isInteger(row)||!Number.isInteger(column)||row<0||column<0||row>=R||column>=C)throw Error('Choose an anchor inside the wall.');if(!repeat&&(row+H>R||column+W>C))throw Error(`This ${W} × ${H} combo does not fit at that anchor. Choose a cell farther from the edge.`);const next=cells.map(r=>r.map(c=>c?{...c}:null));for(let r=row;r<(repeat?R:row+H);r++)for(let c=column;c<(repeat?C:column+W);c++){const v=grid[(r-row)%H][(c-column)%W];next[r][c]=v?{...v}:null}return next}
function generate(id,R,C){const p=rhythms.find(p=>p.id===id);if(!p)throw Error('Unknown rhythm');const grid=p.combo?combos.find(c=>c.id===p.combo).grid:null;return Array.from({length:R},(_,r)=>Array.from({length:C},(_,c)=>grid?{...grid[r%grid.length][c%grid[0].length]}:p.cell(r,c,R,C)))}
window.jaliPatterns={sources,combos,rhythms,rotate,stamp,generate,validCombo};
